package com.solarmind.service; import com.solarmind.dto.response.*; import com.solarmind.repository.LocationRepository; import org.springframework.data.domain.PageRequest; import org.springframework.stereotype.Service; @Service public class LocationService { private final LocationRepository locations; public LocationService(LocationRepository locations){this.locations=locations;} public PagedResponse<LocationResponse> search(String q,int page,int size){var rows=locations.search(q.trim(),PageRequest.of(page,Math.min(size,20)));var content=rows.stream().map(l->new LocationResponse(l.getId(),l.getRegion(),l.getCity(),l.getDistrict(),l.getState(),l.getLatitude(),l.getLongitude())).toList();return new PagedResponse<>(content,page,size,rows.size(),rows.isEmpty()?0:1);} }
